package options

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"strings"
)

// GeneratedHeader starts every generated file.
const GeneratedHeader = "Code generated by dismist-gen from internal/options; DO NOT EDIT."

var scopeSchemaNames = []struct {
	scope Scope
	name  string
}{
	{ScopeSite, "siteSchema"}, {ScopeSiteRF, "siteRFSchema"}, {ScopeAP, "apSchema"},
	{ScopeAPRF, "apRFSchema"}, {ScopeWLAN, "wlanSchema"},
}

func literal(value any) string {
	var buf bytes.Buffer
	encoder := json.NewEncoder(&buf)
	encoder.SetEscapeHTML(false)
	_ = encoder.Encode(value)
	return strings.TrimSuffix(buf.String(), "\n")
}

// GenerateTS writes ui/src/gen/options.gen.ts: metadata for every option
// with a UI presence (basic, advanced and readonly; expert options exist
// only server-side) and one zod schema per scope over the form options.
func GenerateTS(w io.Writer, registry *Registry) error {
	var b strings.Builder
	fmt.Fprintf(&b, "// %s\n", GeneratedHeader)
	b.WriteString(`import { z } from "zod";

export type OptionScope = "site" | "site.rf" | "ap" | "ap.rf" | "wlan";
export type OptionTier = "basic" | "advanced" | "readonly";
export type OptionConfidence = "confirmed" | "likely" | "needs-live-test";
export type OptionDisruption = "none" | "wlan_restart" | "radio_bounce" | "all_radios_bounce" | "stranding_risk";

export interface EnumValueMeta {
  value: string;
  label: string;
  help: string;
  experimental: boolean;
  phase: number;
}

export interface OptionMeta {
  key: string;
  scope: OptionScope;
  label: string;
  help: string;
  control: string;
  type: string;
  enum: EnumValueMeta[];
  min: number | null;
  max: number | null;
  maxBytes: number | null;
  unit: string;
  default: unknown;
  tier: OptionTier;
  confidence: OptionConfidence;
  experimental: boolean;
  disruption: OptionDisruption;
  secret: boolean;
  phase: number;
  firmwarePaths: string[];
  catalogue: string;
  visibleWhen: { key: string; in: string[] }[];
}

`)
	var entries strings.Builder
	for _, option := range registry.All() {
		if option.Tier != TierBasic && option.Tier != TierAdvanced && option.Tier != TierReadonly {
			continue
		}
		enums := make([]map[string]any, 0, len(option.Enum))
		for _, enum := range option.Enum {
			enums = append(enums, map[string]any{
				"value": enum.Value, "label": enum.Label, "help": enum.Help,
				"experimental": option.Confidence == NeedsLiveTest || enum.Confidence == NeedsLiveTest, "phase": enum.Phase,
			})
		}
		visible := option.VisibleWhen
		if visible == nil {
			visible = []Condition{}
		}
		var maxBytes any
		if option.MaxBytes > 0 {
			maxBytes = option.MaxBytes
		}
		paths := option.FirmwarePaths
		if paths == nil {
			paths = []string{}
		}
		fields := []struct {
			name  string
			value any
		}{
			{"key", option.Key}, {"scope", option.Scope}, {"label", option.Label}, {"help", option.Help},
			{"control", option.Control}, {"type", option.Type}, {"enum", enums},
			{"min", option.Min}, {"max", option.Max}, {"maxBytes", maxBytes}, {"unit", option.Unit},
			{"default", option.Default}, {"tier", option.Tier}, {"confidence", option.Confidence},
			{"experimental", option.Confidence == NeedsLiveTest}, {"disruption", option.Disruption},
			{"secret", option.Secret}, {"phase", option.Phase}, {"firmwarePaths", paths},
			{"catalogue", option.Catalogue}, {"visibleWhen", visible},
		}
		fmt.Fprintf(&entries, "  %s: {\n", literal(option.Key))
		for _, field := range fields {
			fmt.Fprintf(&entries, "    %s: %s,\n", field.name, literal(field.value))
		}
		entries.WriteString("  },\n")
	}
	if entries.Len() == 0 {
		b.WriteString("export const optionMeta: Record<string, OptionMeta> = {};\n")
	} else {
		b.WriteString("export const optionMeta: Record<string, OptionMeta> = {\n" + entries.String() + "};\n")
	}
	for _, scope := range scopeSchemaNames {
		var members []string
		for _, option := range registry.ByScope(scope.scope) {
			if option.InForms() {
				members = append(members, fmt.Sprintf("    %s: %s,\n", literal(option.Key), zodType(option)))
			}
		}
		if len(members) == 0 {
			fmt.Fprintf(&b, "\nexport const %s = z.object({}).partial();\n", scope.name)
			continue
		}
		fmt.Fprintf(&b, "\nexport const %s = z\n  .object({\n%s  })\n  .partial();\n", scope.name, strings.Join(members, ""))
	}
	_, err := io.WriteString(w, b.String())
	return err
}

func zodType(o Option) string {
	bounds := func(base string) string {
		if o.Min != nil {
			base += fmt.Sprintf(".min(%d)", *o.Min)
		}
		if o.Max != nil {
			base += fmt.Sprintf(".max(%d)", *o.Max)
		}
		return base
	}
	switch o.Type {
	case "string":
		if len(o.Enum) > 0 {
			values := make([]string, 0, len(o.Enum))
			for _, enum := range o.Enum {
				values = append(values, enum.Value)
			}
			return "z.enum(" + literal(values) + ")"
		}
		if o.MaxBytes > 0 {
			// zod counts UTF-16 units; the server checks bytes.
			return fmt.Sprintf("z.string().max(%d)", o.MaxBytes)
		}
		return "z.string()"
	case "int":
		return bounds("z.number().int()")
	case "bool":
		return "z.boolean()"
	case "[]int":
		return "z.array(" + bounds("z.number().int()") + ")"
	case "[]string":
		return "z.array(z.string())"
	default:
		return "z.record(z.string(), z.unknown())"
	}
}

// GenerateMarkdown writes docs/design/options.gen.md, a reference table of
// every option including the expert-tier defaults.
func GenerateMarkdown(w io.Writer, registry *Registry) error {
	var b strings.Builder
	fmt.Fprintf(&b, "<!-- %s -->\n\n# Option reference\n\n", GeneratedHeader)
	b.WriteString("Every typed option in `internal/options`, generated by `go generate ./internal/options`.\n\n")
	all := registry.All()
	if len(all) == 0 {
		b.WriteString("No options are declared yet (phase 0 ships the registry framework only).\n")
		_, err := io.WriteString(w, b.String())
		return err
	}
	b.WriteString("| Key | Scope | Tier | Control | Type | Default | Legacy default | Confidence | Disruption | Firmware paths | Catalogue |\n")
	b.WriteString("| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\n")
	cell := func(s string) string { return strings.ReplaceAll(s, "|", "\\|") }
	for _, option := range all {
		legacy := "same"
		if option.LegacyDefault != nil {
			legacy = literal(option.LegacyDefault)
		}
		fmt.Fprintf(&b, "| `%s` | %s | %s | %s | %s | %s | %s | %s | %s | %s | %s |\n",
			option.Key, option.Scope, option.Tier, cell(option.Control), cell(option.Type),
			cell(literal(option.Default)), cell(legacy), option.Confidence, option.Disruption,
			cell("`"+strings.Join(option.FirmwarePaths, "`, `")+"`"), cell(option.Catalogue))
	}
	_, err := io.WriteString(w, b.String())
	return err
}
